-- MANUAL STAGING ACTIVATION ONLY, AFTER SEPARATE APPROVAL.
-- Never include in automatic seeds/migrations. psql only; do not use SQL Editor.
\set ON_ERROR_STOP on
begin;
set local lock_timeout='2s';
set local statement_timeout='30s';
select set_config('menu_man.demo_environment', :'menu_man_environment', true);
select set_config('menu_man.demo_project', :'menu_man_staging_project_ref', true);
select set_config('menu_man.demo_host', :'HOST', true);
select set_config('menu_man.demo_user', :'USER', true);
select set_config('menu_man.demo_approval', :'approve_super_tacos_demo', true);
select set_config('menu_man.demo_merchant', :'square_merchant_id', true);
select set_config('menu_man.demo_location', :'square_location_id', true);
do $$
declare tenant constant uuid := '20000000-0000-4000-8000-000000000001';
begin
  if current_setting('menu_man.demo_environment') <> 'staging'
    or current_setting('menu_man.demo_project') <> 'jjvongzvtnzlvwdfcnjk'
    or current_setting('menu_man.demo_approval') <> 'activate-super-tacos-demo'
    or not (current_setting('menu_man.demo_host')='db.jjvongzvtnzlvwdfcnjk.supabase.co'
      or (current_setting('menu_man.demo_host') ~ '^[a-z0-9-]+[.]pooler[.]supabase[.]com$'
        and current_setting('menu_man.demo_user')='postgres.jjvongzvtnzlvwdfcnjk'))
    or btrim(current_setting('menu_man.demo_merchant'))=''
    or btrim(current_setting('menu_man.demo_location'))=''
  then raise exception 'Verified Staging connection and explicit demo activation approval are required.'; end if;
  if not exists(select 1 from public.restaurants where id=tenant and slug='super-tacos' and not is_indexable)
    or (select count(*) from public.menus where restaurant_id=tenant)<>1
    or not exists(select 1 from public.menus where id='20000000-0000-4000-8000-000000000002' and restaurant_id=tenant)
    or (select count(*) from public.menu_items where restaurant_id=tenant)<>12
    or (select count(*) from public.menu_sections where menu_id='20000000-0000-4000-8000-000000000002')<>4
    or exists(select 1 from public.menu_sections where menu_id='20000000-0000-4000-8000-000000000002' and id::text !~ '^20000000-0000-4000-8000-00000000010[1-4]$')
    or (select count(*) from public.menu_section_items p join public.menu_sections s on s.id=p.section_id where s.menu_id='20000000-0000-4000-8000-000000000002')<>12
    or exists(select 1 from public.menu_items where restaurant_id=tenant and id::text !~ '^20000000-0000-4000-8000-0000000002(0[1-9]|1[0-2])$')
    or exists(select 1 from public.orders where restaurant_id=tenant)
    or exists(select 1 from public.restaurant_payment_connections where restaurant_id=tenant)
    or exists(select 1 from public.modifier_groups where restaurant_id=tenant)
    or exists(select 1 from public.restaurant_business_hours where restaurant_id=tenant)
    or exists(select 1 from public.restaurant_catering_settings where restaurant_id=tenant and (coalesce((settings->>'enabled')::boolean,false) or coalesce((settings->>'notifyOwner')::boolean,false)))
    or not exists(select 1 from public.restaurant_ordering_settings where restaurant_id=tenant and not pickup_enabled)
  then raise exception 'Expected untouched browse-only Super Tacos fixture not found. Stop and review; nothing changed.'; end if;
  -- Never adopt colliding reserved IDs from another tenant/menu.
  if exists(select 1 from public.menu_items where id::text ~ '^20000000-0000-4000-8000-0000000002[0-9]{2}$' and restaurant_id<>tenant)
    or exists(select 1 from public.menu_sections where id::text ~ '^20000000-0000-4000-8000-00000000010[1-6]$' and menu_id<>'20000000-0000-4000-8000-000000000002')
    or exists(select 1 from public.modifier_groups where id::text ~ '^20000000-0000-4000-8000-00000000050[1-4]$')
    or exists(select 1 from public.modifier_options where id::text ~ '^20000000-0000-4000-8000-0000000006[0-9]{2}$')
    or exists(select 1 from public.menu_section_items where id::text ~ '^20000000-0000-4000-8000-0000000003[0-9]{2}$' and item_id::text !~ '^20000000-0000-4000-8000-0000000002[0-9]{2}$')
  then raise exception 'Reserved fixture identity collision; no data was adopted.'; end if;
  if exists(select 1 from public.payment_provider_references where provider_key='square' and environment='sandbox'
    and ((reference_kind='merchant' and external_id=current_setting('menu_man.demo_merchant'))
      or (reference_kind='location' and external_id=current_setting('menu_man.demo_location'))))
  then raise exception 'Use a dedicated Sandbox seller/location. Existing payment references must not be reassigned.'; end if;
end;
$$;

-- Generated from super-tacos-demo.json. Review JSON and generator together.
do $$ begin if exists(select 1 from public.menu_section_items actual join (values ('20000000-0000-4000-8000-000000000301'::uuid,'20000000-0000-4000-8000-000000000201'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000302'::uuid,'20000000-0000-4000-8000-000000000202'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000303'::uuid,'20000000-0000-4000-8000-000000000203'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000304'::uuid,'20000000-0000-4000-8000-000000000204'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000305'::uuid,'20000000-0000-4000-8000-000000000205'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000306'::uuid,'20000000-0000-4000-8000-000000000206'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000307'::uuid,'20000000-0000-4000-8000-000000000207'::uuid,'20000000-0000-4000-8000-000000000103'::uuid),('20000000-0000-4000-8000-000000000308'::uuid,'20000000-0000-4000-8000-000000000208'::uuid,'20000000-0000-4000-8000-000000000103'::uuid),('20000000-0000-4000-8000-000000000309'::uuid,'20000000-0000-4000-8000-000000000209'::uuid,'20000000-0000-4000-8000-000000000103'::uuid),('20000000-0000-4000-8000-000000000310'::uuid,'20000000-0000-4000-8000-000000000210'::uuid,'20000000-0000-4000-8000-000000000104'::uuid),('20000000-0000-4000-8000-000000000311'::uuid,'20000000-0000-4000-8000-000000000211'::uuid,'20000000-0000-4000-8000-000000000104'::uuid),('20000000-0000-4000-8000-000000000312'::uuid,'20000000-0000-4000-8000-000000000212'::uuid,'20000000-0000-4000-8000-000000000104'::uuid),('20000000-0000-4000-8000-000000000313'::uuid,'20000000-0000-4000-8000-000000000213'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000314'::uuid,'20000000-0000-4000-8000-000000000214'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000315'::uuid,'20000000-0000-4000-8000-000000000215'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000316'::uuid,'20000000-0000-4000-8000-000000000216'::uuid,'20000000-0000-4000-8000-000000000101'::uuid),('20000000-0000-4000-8000-000000000317'::uuid,'20000000-0000-4000-8000-000000000217'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000318'::uuid,'20000000-0000-4000-8000-000000000218'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000319'::uuid,'20000000-0000-4000-8000-000000000219'::uuid,'20000000-0000-4000-8000-000000000102'::uuid),('20000000-0000-4000-8000-000000000320'::uuid,'20000000-0000-4000-8000-000000000220'::uuid,'20000000-0000-4000-8000-000000000103'::uuid),('20000000-0000-4000-8000-000000000321'::uuid,'20000000-0000-4000-8000-000000000221'::uuid,'20000000-0000-4000-8000-000000000105'::uuid),('20000000-0000-4000-8000-000000000322'::uuid,'20000000-0000-4000-8000-000000000222'::uuid,'20000000-0000-4000-8000-000000000105'::uuid),('20000000-0000-4000-8000-000000000323'::uuid,'20000000-0000-4000-8000-000000000223'::uuid,'20000000-0000-4000-8000-000000000105'::uuid),('20000000-0000-4000-8000-000000000324'::uuid,'20000000-0000-4000-8000-000000000224'::uuid,'20000000-0000-4000-8000-000000000105'::uuid),('20000000-0000-4000-8000-000000000325'::uuid,'20000000-0000-4000-8000-000000000225'::uuid,'20000000-0000-4000-8000-000000000105'::uuid),('20000000-0000-4000-8000-000000000326'::uuid,'20000000-0000-4000-8000-000000000226'::uuid,'20000000-0000-4000-8000-000000000104'::uuid),('20000000-0000-4000-8000-000000000327'::uuid,'20000000-0000-4000-8000-000000000227'::uuid,'20000000-0000-4000-8000-000000000104'::uuid),('20000000-0000-4000-8000-000000000328'::uuid,'20000000-0000-4000-8000-000000000228'::uuid,'20000000-0000-4000-8000-000000000106'::uuid),('20000000-0000-4000-8000-000000000329'::uuid,'20000000-0000-4000-8000-000000000229'::uuid,'20000000-0000-4000-8000-000000000106'::uuid),('20000000-0000-4000-8000-000000000330'::uuid,'20000000-0000-4000-8000-000000000230'::uuid,'20000000-0000-4000-8000-000000000106'::uuid)) expected(id,item_id,section_id) on actual.id=expected.id where actual.item_id<>expected.item_id or actual.section_id<>expected.section_id) then raise exception 'Unexpected placement identity; stop without adopting it.'; end if; end; $$;
update public.restaurants set name='Super Tacos',
  tagline='Bright salsas. Bold taco flavor.',
  description='Fresh tortillas, flame-grilled favorites, and house salsas bring a little sunshine to every bite. Find your new favorite, make it your own, and enjoy the good stuff.',
  logo_url='/img/super-tacos/logo.svg',
  hero_image_url='/img/super-tacos/tacos.jpg',
  phone=null,
  address_line1=null,
  city=null,
  state=null,
  postal_code=null,
  timezone='America/Los_Angeles',
  theme_preset='classic-red', theme_overrides='{"primary":"#163b32","accent":"#b53f1a","background":"#fff8e8","surface":"#ffffff","text":"#17352b","mutedText":"#526257","borderRadius":"18px"}'::jsonb, is_indexable=false where id='20000000-0000-4000-8000-000000000001' and slug='super-tacos';
update public.restaurant_ordering_settings set pickup_enabled=true,asap_enabled=true,scheduled_pickup_enabled=true,pickup_lead_time_minutes=20,pickup_cutoff_minutes_before_close=20,pickup_slot_interval_minutes=15,advance_order_days=3,pickup_max_orders_per_interval=10,tax_strategy='restaurant_percentage',tax_rate_basis_points=825,customer_name_required=true,customer_email_required=false,customer_phone_required=false where restaurant_id='20000000-0000-4000-8000-000000000001';
alter table public.restaurant_notification_settings add constraint super_tacos_demo_no_email check (restaurant_id<>'20000000-0000-4000-8000-000000000001' or (not customer_order_confirmation_email and not customer_ready_for_pickup_email and not customer_refund_confirmation_email and not internal_new_paid_order_email and not internal_payment_refund_exception_email and internal_email_recipient is null));
alter table public.restaurant_payment_connections add constraint super_tacos_demo_sandbox_only check (restaurant_id<>'20000000-0000-4000-8000-000000000001' or (provider_key='square' and environment='sandbox' and coalesce(provider_metadata->>'publicDemo','')='true'));
-- All demo order sources use one transaction lock, including simultaneous new
-- idempotency keys. Quotas and the authoritative order commit or roll back together.
create function public.create_demo_order_v1(p_restaurant_slug text,p_idempotency_key text,p_request jsonb,p_source_hash text)
returns jsonb language plpgsql security definer set search_path='' set lock_timeout='2s' as $$
declare
  tenant constant uuid := '20000000-0000-4000-8000-000000000001';
  current_window timestamptz;
  accepted integer;
  key text;
begin
  if p_restaurant_slug is distinct from 'super-tacos'
    or not exists(select 1 from public.restaurants where id=tenant and slug=p_restaurant_slug and is_active)
    or p_source_hash is null or p_source_hash !~ '^[0-9a-f]{64}$' or p_source_hash=repeat('0',64)
  then raise exception 'MM_ORDERING_DISABLED|Demo checkout configuration is unavailable.'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('public-demo:'||tenant::text,0));
  -- Canonical checkout still validates payload/fingerprint and session ownership.
  if exists(select 1 from public.orders where restaurant_id=tenant and idempotency_key=pg_catalog.lower(p_idempotency_key)) then
    return public.create_order_v1(p_restaurant_slug,p_idempotency_key,p_request);
  end if;
  current_window:=pg_catalog.date_bin('10 minutes'::interval,now(),'2000-01-01'::timestamptz);
  delete from public.checkout_creation_windows where restaurant_id=tenant and window_start<now()-interval '1 day';
  foreach key in array array[p_source_hash,repeat('0',64)] loop
    values(tenant,key,current_window,1)
    on conflict(restaurant_id,source_hash,window_start) do update set creation_count=counter.creation_count+1
      where counter.creation_count<case when key=repeat('0',64) then 50 else 5 end
    returning creation_count into accepted;
    if accepted is null then raise exception 'MM_CHECKOUT_RATE_LIMITED|600'; end if;
  end loop;
  perform pg_catalog.set_config('menu_man.demo_order_entry','allowed',true);
  return public.create_order_v1(p_restaurant_slug,p_idempotency_key,p_request);
end;
$$;
revoke all on function public.create_demo_order_v1(text,text,jsonb,text) from public,anon,authenticated,service_role;
grant execute on function public.create_demo_order_v1(text,text,jsonb,text) to service_role;

-- Old Preview builds still share Staging. They cannot bypass the demo limiter
-- using the ordinary create_order RPC. Existing-order reads/replays are still
-- governed by the canonical contracts; obsolete deployments must be retired.
create function private.guard_super_tacos_demo_order_v1()
returns trigger language plpgsql set search_path='' as $$
begin
  if new.restaurant_id='20000000-0000-4000-8000-000000000001'::uuid
    and pg_catalog.current_setting('menu_man.demo_order_entry',true) is distinct from 'allowed'
  then raise exception 'MM_ORDERING_DISABLED|Use the current demo checkout.'; end if;
  return new;
end;
$$;
revoke all on function private.guard_super_tacos_demo_order_v1() from public,anon,authenticated,service_role;
create trigger guard_super_tacos_demo_order before insert on public.orders
for each row execute function private.guard_super_tacos_demo_order_v1();

-- Defense against future preference changes: no customer or owner order-email
-- record can enter the delivery queue for this fictional tenant.
create function private.suppress_super_tacos_demo_email_v1()
returns trigger language plpgsql set search_path='' as $$
begin
  if new.restaurant_id='20000000-0000-4000-8000-000000000001'::uuid then return null; end if;
  return new;
end;
$$;
revoke all on function private.suppress_super_tacos_demo_email_v1() from public,anon,authenticated,service_role;
create trigger suppress_super_tacos_demo_email before insert or update on public.notification_outbox
for each row execute function private.suppress_super_tacos_demo_email_v1();

commit;
