insert into public.restaurant_notification_settings(restaurant_id,customer_order_confirmation_email,customer_ready_for_pickup_email,customer_refund_confirmation_email,internal_new_paid_order_email,internal_payment_refund_exception_email,internal_email_recipient) values ('20000000-0000-4000-8000-000000000001',false,false,false,false,false,null) on conflict(restaurant_id) do update set customer_order_confirmation_email=false,customer_ready_for_pickup_email=false,customer_refund_confirmation_email=false,internal_new_paid_order_email=false,internal_payment_refund_exception_email=false,internal_email_recipient=null;
